{"code": "from dateutil.easter import easter
from dateutil.parser import parse

date_str = 'Sat Oct 11 17:13:46 UTC 2003'
year = parse(date_str).year

# Find the first year after 2003 where the 13th of month 8 (August) is a Friday
for year in range(2004, 10000):
    easter_date = easter.easter(year, method='easter')
    if easter_date.month == 8 and easter_date.day == 13 and easter_date.weekday() == 4:
        print(f'And the Easter of that year is: {easter_date.strftime("%Y-%m-%d")}
        break"}

